from checkpoint_engine.distributed.vllm_compat import create_stateless_process_group


class CurrentProcessGroup:
    def __init__(self, rank: int, world_size: int, store: object):
        self.arguments = rank, world_size, store


class LegacyProcessGroup:
    def __init__(self, rank: int, world_size: int, store: object, socket: object):
        self.arguments = rank, world_size, store, socket


def test_current_vllm_process_group_signature():
    store = object()

    group = create_stateless_process_group(
        CurrentProcessGroup,
        rank=2,
        world_size=8,
        store=store,
    )

    assert group.arguments == (2, 8, store)


def test_legacy_vllm_process_group_signature():
    store = object()

    group = create_stateless_process_group(
        LegacyProcessGroup,
        rank=2,
        world_size=8,
        store=store,
    )

    assert group.arguments == (2, 8, store, None)

"""Hardware-gated tests for the native SYCL IPC memory handler on Intel XPU.

These are skipped unless an Intel GPU is present and the SYCL IPC extension can
be built (needs an oneAPI ``icpx`` with SYCL ipc_memory support). They are marked
``gpu`` so CPU-only CI (``-m "not gpu"``) skips them.
"""

import os

import pytest
import torch


pytestmark = pytest.mark.gpu


def _xpu_ipc_available() -> bool:
    try:
        if not (hasattr(torch, "xpu") and torch.xpu.is_available()):
            return False
        from checkpoint_engine import xpu_ipc

        return xpu_ipc.is_available()
    except Exception:  # noqa: BLE001
        return False


skip_no_xpu_ipc = pytest.mark.skipif(
    not _xpu_ipc_available(), reason="Intel XPU with buildable SYCL ipc_memory extension required"
)

_N_TENSORS = 8


def _gen_tensors() -> dict[str, torch.Tensor]:
    gen = torch.Generator().manual_seed(0)
    return {
        f"w{i}": (torch.randn(128 + i, 64, generator=gen) * 50).to(torch.bfloat16)
        for i in range(_N_TENSORS)
    }
